-- Languages: Bosnian, Kazakh, Uzbek, Azerbaijani and Haitian Creole added, and 959 posts that the AI had put under "Other"
-- moved to their real language (Spanish, Hebrew, Italian, Catalan, Polish, Haitian Creole, Kazakh, Basque...).
-- Built on 2026-10-20 from the 1,506 "Other" posts left after languages-galician-basque.sql: language detected from the
-- alphabet and the franc detector, then every post read and decided by hand (Persian, posts in two or three languages
-- at once and texts too short to tell stay "Other"). Run AFTER languages-galician-basque.sql. Safe to run again.

insert into public.idea_catalog (category, name) select 'language', n from unnest(array['Bosnian','Kazakh','Uzbek','Azerbaijani','Haitian Creole','Galician','Basque']) n
  on conflict (category, name) do nothing;

create temporary table lang_fix (idea_id bigint primary key, lang text not null) on commit drop;
